// Shared helper for the rest of this audit run.
//
// ROOT CAUSE CONFIRMED (see step 1 findings): next.config.ts unconditionally
// adds `upgrade-insecure-requests` to the CSP for every environment, and the
// shared nginx in front of this box also sends `Strict-Transport-Security` on
// the plain-HTTP-only staging port 8080. Together, a real browser hitting
// http://51.79.162.96:8080 upgrades EVERY subresource (css/js/fonts/images) to
// https://...:8080, which has no TLS listener -> 100% of assets fail to load,
// no JS ever hydrates, and even the plain server-rendered <form action=""> gets
// its submit target silently upgraded to https too, which the page's own CSP
// `form-action 'self'` then refuses (scheme mismatch = different origin) and
// BLOCKS client-side. Net effect: NO form on this site (register/login/deploy/
// checkout/cancel) can be submitted by a real, unmodified browser today. This
// is reported as a hard BLOCKER for step 1 in the final report.
//
// To still audit steps 2-7 for their OWN, independent defects (rather than
// leaving the whole rest of the journey as "unknown"), the rest of this run
// uses `newUnblockedContext()` below, which strips `upgrade-insecure-requests`
// from the CSP response header and drops `Strict-Transport-Security` entirely
// so the browser stops upgrading same-origin requests. This is a diagnostic
// workaround ONLY — no real customer can do this. Every step from here on is
// reported with that caveat.
import { chromium } from "playwright";

export const BASE = "http://51.79.162.96:8080";

export async function newUnblockedContext(browser, opts = {}) {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 950 }, ...opts });
  await ctx.route("**/*", async (route) => {
    const response = await route.fetch();
    const headers = { ...response.headers() };
    if (headers["content-security-policy"]) {
      headers["content-security-policy"] = headers["content-security-policy"]
        .split(";")
        .map((d) => d.trim())
        .filter((d) => d !== "upgrade-insecure-requests")
        .join("; ");
    }
    delete headers["strict-transport-security"];
    await route.fulfill({ response, headers, body: await response.body() });
  });
  return ctx;
}

export function attachDiagnostics(page, findings) {
  page.on("console", (msg) => {
    if (["error", "warning"].includes(msg.type())) findings.push(`[console.${msg.type()}] ${msg.text()}`);
  });
  page.on("requestfailed", (r) => findings.push(`[requestfailed] ${r.url()} :: ${r.failure()?.errorText}`));
  page.on("response", (resp) => {
    if (resp.status() >= 400) findings.push(`[http ${resp.status()}] ${resp.request().method()} ${resp.url()}`);
  });
  page.on("pageerror", (err) => findings.push(`[pageerror] ${err.message}`));
}

export { chromium };

import { chromium, newUnblockedContext, attachDiagnostics, BASE } from "./lib.mjs";
import { mkdirSync, writeFileSync } from "node:fs";

const OUT = "/tmp/claude-0/-/a847f019-50a6-4b60-bcba-1133f2a3ca8a/scratchpad";
mkdirSync(OUT, { recursive: true });

const rand = Math.random().toString(36).slice(2, 10);
const EMAIL = `nx-e2e-${rand}@example.com`;
const PASSWORD = "TestPass123";
const NAME = "NX E2E Tester";

const browser = await chromium.launch();
const ctx = await newUnblockedContext(browser);
const page = await ctx.newPage();
const findings = [];
attachDiagnostics(page, findings);

await page.goto(`${BASE}/register`, { waitUntil: "networkidle" });
await page.waitForTimeout(1000);
await page.screenshot({ path: `${OUT}/e2e-01-register-form.png`, fullPage: true });

await page.fill('input[name="name"]', NAME);
await page.fill('input[name="email"]', EMAIL);
await page.fill('input[name="password"]', PASSWORD);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/register"), { timeout: 20000 }).catch(() => {}),
  page.click('button:has-text("Create account")'),
]);
await page.waitForTimeout(1500);
const afterUrl = page.url();
await page.screenshot({ path: `${OUT}/e2e-02-after-register.png`, fullPage: true });

writeFileSync(`${OUT}/creds.json`, JSON.stringify({ email: EMAIL, password: PASSWORD, name: NAME }, null, 2));
await ctx.storageState({ path: `${OUT}/storageState.json` });
writeFileSync(`${OUT}/step1-findings.json`, JSON.stringify({ afterUrl, findings }, null, 2));

console.log("EMAIL=" + EMAIL);
console.log("PASSWORD=" + PASSWORD);
console.log("AFTER_REGISTER_URL=" + afterUrl);
console.log("FINDINGS:\n" + findings.join("\n"));

await browser.close();

